  "use strict";
  /* 預約狀態機：瀏覽匿名資訊 → 選擇服務 → 閱讀並勾選同意 → 送出最小資料 → 等待回覆。
     第 1 步不收任何欄位；選好服務後先閱讀並勾選同意，才出現偏好時段與個人欄位。 */
  var SERVICES = {
    "初談": { len: "30 分鐘", modes: ["現場", "線上"] },
    "個別諮商": { len: "50 分鐘", modes: ["現場"] },
    "伴侶諮商": { len: "80 分鐘", modes: ["現場"] },
    "線上諮商": { len: "50 分鐘", modes: ["線上"] }
  };
  var SLOTS = [
    { id: "1006-1400", date: "10/06（二）", time: "14:00", mode: "現場", ok: true },
    { id: "1006-1930", date: "10/06（二）", time: "19:30", mode: "現場", ok: false },
    { id: "1007-1000", date: "10/07（三）", time: "10:00", mode: "線上", ok: true },
    { id: "1007-1930", date: "10/07（三）", time: "19:30", mode: "線上", ok: true },
    { id: "1008-1400", date: "10/08（四）", time: "14:00", mode: "現場", ok: true },
    { id: "1008-1930", date: "10/08（四）", time: "19:30", mode: "線上", ok: false },
    { id: "1009-1000", date: "10/09（五）", time: "10:00", mode: "現場", ok: true },
    { id: "1009-1400", date: "10/09（五）", time: "14:00", mode: "線上", ok: true },
    { id: "1013-1930", date: "10/13（二）", time: "19:30", mode: "現場", ok: true }
  ];
  var STEPS = ["瀏覽匿名資訊", "選擇服務", "閱讀並勾選同意", "送出最小資料", "等待回覆"];
  var $ = function (s) { return document.querySelector(s); };
  var $$ = function (s) { return Array.prototype.slice.call(document.querySelectorAll(s)); };
  var form = $("#booking-form"), slotBox = $("#slot-list"), pickSlot = $("#pick-slot"), intake = $("#intake");
  var confirmBox = $("#confirm"), summary = $("#pick-summary"), stateLine = $("#state-line");
  var st = { svc: null, slot: null, submitted: false, enteredService: false };
  var consentStep = $("#consent-step"), consent = $("input[name=consent]"), submit = $("#submit");

  function slotText(id) {
    if (id === "any") { return "都可以，由本所協調時間"; }
    var s = SLOTS.filter(function (x) { return x.id === id; })[0];
    return s ? s.date + " " + s.time + " " + s.mode : "";
  }
  function el(tag, cls, text) {
    var n = document.createElement(tag);
    if (cls) { n.className = cls; }
    if (text !== undefined) { n.textContent = text; }
    return n;
  }
  function renderSlots() {
    slotBox.textContent = "";
    var svc = SERVICES[st.svc];
    if (!svc) { return; }
    var days = [];
    SLOTS.forEach(function (s) {
      if (svc.modes.indexOf(s.mode) < 0) { return; }
      var d = days.filter(function (x) { return x.date === s.date; })[0];
      if (!d) { d = { date: s.date, list: [] }; days.push(d); }
      d.list.push(s);
    });
    days.forEach(function (d) {
      var row = el("div", "slot-day");
      row.appendChild(el("div", "slot-date", d.date));
      var chips = el("div", "slot-chips");
      d.list.forEach(function (s) {
        var lab = el("label", "slot" + (s.ok ? "" : " is-taken"));
        var inp = document.createElement("input");
        inp.type = "radio"; inp.name = "slot"; inp.value = s.id; inp.disabled = !s.ok; inp.required = true;
        inp.addEventListener("change", function () { st.slot = inp.value; sync(); });
        lab.appendChild(inp);
        lab.appendChild(el("span", "slot-t", s.time));
        lab.appendChild(el("span", "slot-m", s.mode));
        if (!s.ok) { lab.appendChild(el("span", "slot-n", "已有人預約")); }
        chips.appendChild(lab);
      });
      row.appendChild(chips);
      slotBox.appendChild(row);
    });
    var any = el("label", "slot slot-any");
    var ai = document.createElement("input");
    ai.type = "radio"; ai.name = "slot"; ai.value = "any"; ai.required = true;
    ai.addEventListener("change", function () { st.slot = "any"; sync(); });
    any.appendChild(ai);
    any.appendChild(el("span", "slot-t", "都可以，由本所協調"));
    slotBox.appendChild(any);
  }
  function filled() {
    var n = 0;
    if ($("#f-name").value.trim()) { n++; }
    if ($("#f-contact").value.trim()) { n++; }
    if (st.slot) { n++; }
    if (st.svc) { n++; }
    if ($("#f-need").value.trim()) { n++; }
    return n;
  }
  function paintCount() {
    var flags = { name: !!$("#f-name").value.trim(), contact: !!$("#f-contact").value.trim(), slot: !!st.slot, service: !!st.svc, need: !!$("#f-need").value.trim() };
    $$("[data-count]").forEach(function (o) { o.textContent = String(filled()); });
    $$("[data-field]").forEach(function (li) {
      var on = !!flags[li.getAttribute("data-field")];
      li.classList.toggle("is-filled", on);
      var s = li.querySelector("[data-status]");
      if (s) { s.textContent = on ? "已填" : (li.getAttribute("data-field") === "need" ? "未填（可不寫）" : "未填"); }
    });
  }
  function step() {
    if (st.submitted) { return 5; }
    if (!st.svc) { return st.enteredService ? 2 : 1; }
    return consent.checked ? 4 : 3;
  }
  function sync() {
    var n = step();
    var choosing = !!(st.svc && !st.submitted);
    consentStep.hidden = !choosing;
    consentStep.disabled = !choosing;
    var show = !!(choosing && consent.checked);
    pickSlot.hidden = !show;
    pickSlot.disabled = !show;
    submit.hidden = !choosing;
    intake.hidden = !show;
    intake.disabled = !show;
    form.hidden = st.submitted;
    confirmBox.hidden = !st.submitted;
    var svc = SERVICES[st.svc];
    summary.textContent = !st.svc ? "還沒選服務" : st.svc + "（" + svc.len + "）・" + (st.slot ? slotText(st.slot) : "還沒選時段");
    stateLine.textContent = "目前在第 " + n + " 步／共 5 步：" + STEPS[n - 1];
    $$("[data-step]").forEach(function (li) {
      var k = parseInt(li.getAttribute("data-step"), 10);
      if (k === n) { li.setAttribute("aria-current", "step"); } else { li.removeAttribute("aria-current"); }
      li.classList.toggle("is-done", k < n);
    });
    $$("[data-after]").forEach(function (n) {
      if (!n.getAttribute("data-before")) { n.setAttribute("data-before", n.textContent); }
      n.textContent = st.submitted ? n.getAttribute("data-after") : n.getAttribute("data-before");
    });
    paintCount();
  }
  // Entering the service section is step 2, before a service is selected.
  function enterService() {
    if (!st.enteredService && !st.submitted) { st.enteredService = true; sync(); }
  }
  new IntersectionObserver(function (entries) {
    if (entries.some(function (entry) { return entry.isIntersecting; })) { enterService(); }
  }, { threshold: 0.2 }).observe($("#pick-svc"));
  $("#pick-svc").addEventListener("focusin", enterService);
  $$("#svc-list input[name=service]").forEach(function (r) {
    r.addEventListener("change", function () {
      st.svc = r.value; consent.checked = false; clearDetails(); renderSlots(); sync();
    });
  });
  ["#f-name", "#f-contact", "#f-need"].forEach(function (s) { $(s).addEventListener("input", paintCount); });
  function clearDetails() {
    // Retracting consent also clears hidden details so the counter reflects this step.
    st.slot = null;
    $$("#slot-list input").forEach(function (r) { r.checked = false; });
    ["#f-name", "#f-contact", "#f-need"].forEach(function (s) { $(s).value = ""; });
  }
  consent.addEventListener("change", function () {
    if (!consent.checked) { clearDetails(); }
    sync();
  });

  function pad(n) { return (n < 10 ? "0" : "") + n; }
  form.addEventListener("submit", function (e) {
    e.preventDefault();
    var name = $("#f-name").value.trim(), contact = $("#f-contact").value.trim(), need = $("#f-need").value.trim();
    var d = new Date();
    var when = d.getFullYear() + "/" + pad(d.getMonth() + 1) + "/" + pad(d.getDate()) + " " + pad(d.getHours()) + ":" + pad(d.getMinutes());
    // 使用者輸入一律用 textContent 顯示（逸出），不用 innerHTML
    $("#c-name").textContent = name;
    $("#c-contact").textContent = contact;
    $("#c-svc").textContent = st.svc;
    $("#c-slot").textContent = slotText(st.slot);
    $("#c-need").textContent = need || "（沒有填）";
    $("#c-consent-time").textContent = when;
    $("#m-intake").textContent = "最近一筆：" + name + "／" + contact + "／" + slotText(st.slot) + "／" + st.svc + "／" + (need || "沒有填");
    $("#m-consent").textContent = "最近一筆：已同意，" + when + "，諮商紀錄依法至少保存十年";
    st.submitted = true;
    sync();
    confirmBox.focus();
    confirmBox.scrollIntoView({ block: "start" });
  });
  $("#reset").addEventListener("click", function () {
    form.reset();
    st = { svc: null, slot: null, submitted: false };
    renderSlots();
    sync();
    $("#booking").scrollIntoView({ block: "start" });
  });
  sync();
})();

</script>
